# Generated by build.py from recipe.yml for recipe http-serve-a-small-website. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site site/css site/js site/img site/data site/downloads site/fonts
printf '%s\n' '<!doctype html><title>Home</title><link rel=stylesheet href=css/site.css><script src=js/app.js></script><img src=img/logo.png>' > site/index.html
printf '%s\n' 'body { margin: 0; }' > site/css/site.css
printf '%s\n' 'console.log('\''loaded'\'');' > site/js/app.js
printf '%s\n' 'not really a PNG' > site/img/logo.png
printf '%s\n' '<svg xmlns='\''http://www.w3.org/2000/svg'\''/>' > site/img/icon.svg
printf '%s\n' '{"items": []}' > site/data/menu.json
printf '%s\n' 'an extension surl does not know' > site/downloads/notes.xyz
printf '%s\n' 'no extension at all' > site/downloads/README
printf '%s\n' 'not really a JPEG' > site/img/photo.jpg
printf '%s\n' 'not really an icon' > site/favicon.ico
printf '%s\n' 'not really a font' > site/fonts/body.woff2
printf '%s\n' 'export {};' > site/js/module.mjs
surl --directory site http://127.0.0.1:8080/ &
sleep 1
curl -s --remote-name-all --create-dirs --output-dir fetched -w "%{url.path} %{http_code} %{content_type}\n" http://127.0.0.1:8080/index.html http://127.0.0.1:8080/css/site.css http://127.0.0.1:8080/js/app.js http://127.0.0.1:8080/img/logo.png http://127.0.0.1:8080/img/icon.svg http://127.0.0.1:8080/data/menu.json
kill $(jobs -p)
